pipeline {
  agent none                       // do not pin an executor for the whole run

  options {
    timeout(time: 45, unit: 'MINUTES')
    buildDiscarder(logRotator(numToKeepStr: '30', artifactNumToKeepStr: '10'))
    disableConcurrentBuilds(abortPrevious: true)
    timestamps()
    skipDefaultCheckout()          // we call checkout scm explicitly per agent
  }

  parameters {
    choice(name: 'ENVIRONMENT', choices: ['staging', 'production'])
    booleanParam(name: 'SKIP_E2E', defaultValue: false)
  }

  environment {
    REGISTRY = 'ghcr.io/acme'
    // A usernamePassword credential binds THREE vars:
    //   REGISTRY_CREDS, REGISTRY_CREDS_USR, REGISTRY_CREDS_PSW
    REGISTRY_CREDS = credentials('ghcr-push')
  }

  stages {
    stage('Build') {
      agent { docker { image 'node:20.11.1'; args '-v $HOME/.npm:/root/.npm' } }
      steps {
        checkout scm
        sh 'npm ci && npm run build'
        stash name: 'dist', includes: 'dist/**'      // cross-agent file transfer
      }
    }

    stage('Verify') {
      parallel {
        stage('Unit') {
          agent { docker { image 'node:20.11.1' } }
          steps { checkout scm; sh 'npm ci && npm test -- --reporters=jest-junit' }
          post { always { junit 'reports/*.xml' } }
        }
        stage('Lint') {
          agent { docker { image 'node:20.11.1' } }
          steps { checkout scm; sh 'npm ci && npm run lint' }
        }
        stage('E2E') {
          when { expression { return !params.SKIP_E2E }; beforeAgent true }
          agent { label 'linux && docker' }
          steps { unstash 'dist'; sh './e2e.sh' }
        }
      }
    }

    stage('Publish') {
      when { branch 'main'; beforeAgent true }
      agent { label 'linux && docker' }
      steps {
        unstash 'dist'
        // single quotes: the SHELL expands $REGISTRY_CREDS_PSW, so the secret
        // is never baked into the Groovy-generated script text
        sh '''
          echo "$REGISTRY_CREDS_PSW" | docker login ghcr.io \
            -u "$REGISTRY_CREDS_USR" --password-stdin
          docker build -t "$REGISTRY/api:$GIT_COMMIT" .
          docker push  "$REGISTRY/api:$GIT_COMMIT"
        '''
        archiveArtifacts artifacts: 'dist/**', fingerprint: true
      }
    }

    stage('Approve prod') {
      when { expression { params.ENVIRONMENT == 'production' } }
      // deliberately no agent{}: an input inside a node holds an executor for hours
      steps {
        timeout(time: 2, unit: 'HOURS') {
          input message: 'Deploy to production?', submitter: 'release-managers'
        }
      }
    }

    stage('Deploy') {
      agent { label 'deployer' }
      steps { sh "./deploy.sh ${params.ENVIRONMENT} ${env.GIT_COMMIT}" }
    }
  }

  post {
    failure  { slackSend channel: '#ci', message: "FAILED ${env.BUILD_URL}" }
    fixed    { slackSend channel: '#ci', message: "recovered ${env.BUILD_URL}" }
    cleanup  { cleanWs() }
  }
}

// ---------- shared library: vars/standardService.groovy ----------
def call(Map cfg) {
  pipeline {
    agent { kubernetes { yaml libraryResource('pod-templates/jdk21.yaml') } }
    options { timeout(time: 30, unit: 'MINUTES'); timestamps() }
    stages {
      stage('build') {
        steps { container('jdk') { sh "./gradlew ${cfg.task ?: 'build'}" } }
      }
      stage('publish') {
        when { branch 'main' }
        steps { container('jdk') { sh './gradlew publish' } }
      }
    }
    post {
      always {
        junit allowEmptyResults: true, testResults: '**/build/test-results/**/*.xml'
      }
    }
  }
}

// ---------- consumer Jenkinsfile (the entire file) ----------
@Library('acme-ci@v3.2.1') _        // PINNED to a tag. Never a floating branch.
standardService(task: 'check')

// ---------- CPS traps ----------
// BAD: java.util.regex.Matcher is not Serializable. If a step boundary occurs
// while it is in scope, the build dies with NotSerializableException.
//     def m = (text =~ /v(\d+)/)
//     sh "echo ${m[0][1]}"
//
// GOOD: confine it to a @NonCPS method that returns a plain String.
@NonCPS
String extractVersion(String text) {
  def m = (text =~ /v(\d+\.\d+\.\d+)/)
  return m ? m[0][1] : 'unknown'    // no pipeline steps allowed inside @NonCPS
}

// BAD under CPS: closure iteration can misbehave and may not serialise.
//     items.each { sh "process ${it}" }
// GOOD:
for (int i = 0; i < items.size(); i++) { sh "process ${items[i]}" }

// ---------- credentials: scoped binding beats global env ----------
stage('deploy') {
  steps {
    withCredentials([
      usernamePassword(credentialsId: 'registry',
                       usernameVariable: 'REG_USER', passwordVariable: 'REG_PASS'),
      string(credentialsId: 'deploy-token', variable: 'TOKEN'),
      file(credentialsId: 'kubeconfig-prod', variable: 'KUBECONFIG')
    ]) {
      // single quotes -> the SHELL expands $TOKEN from the environment.
      // double quotes would let Groovy inline the secret into the script text.
      sh 'kubectl --token="$TOKEN" apply -f k8s/'
    }
  }
}

// ---------- building parallel branches dynamically ----------
def branches = [:]
for (int i = 0; i < shards; i++) {
  def n = i                          // capture by value; do not close over the loop var
  branches["shard-${n}"] = { sh "./run-tests.sh --shard ${n}/${shards}" }
}
parallel branches

// Server-side evaluation: the ruleset is in memory, no network in the hot path.
const flags = FlagClient.init({
  sdkKey: process.env.FLAG_SDK_KEY,
  // MUST be explicit and safe: what runs before the first ruleset arrives,
  // and what runs if the flag service is down at boot.
  defaults: { 'checkout.new-pricing-engine': false },
  updateMode: 'streaming',
  cacheTtlSeconds: 60,
});

app.post('/checkout', async (req, res) => {
  const ctx = { userId: req.user.id, plan: req.user.plan, region: req.region };
  // consistent bucketing: hash(flagKey + userId) -> the same user always
  // gets the same variant, in every service, on every request
  if (flags.boolVariation('checkout.new-pricing-engine', ctx, /*fallback*/ false)) {
    return newPricing(req, res);
  }
  return legacyPricing(req, res);
});

// ---- operational kill switch: permanent by design ----
if (!flags.boolVariation('recommendations.enabled', ctx, true)) {
  return [];            // shed a non-essential feature under load, no deploy
}

# ---------- flag hygiene, enforced by CI ----------
# 1) every flag declares an owner and an expiry at creation
# flags.yaml
- key: checkout.new-pricing-engine
  kind: release            # release | experiment | ops | entitlement
  owner: payments-team
  created: 2026-07-01
  expires: 2026-08-15      # release toggles are temporary. ops toggles are not.

# 2) a CI check that fails on expired release toggles
python3 - <<'PY'
import yaml, datetime, sys
today = datetime.date.today()
bad = [f for f in yaml.safe_load(open('flags.yaml'))
       if f['kind'] in ('release','experiment')
       and f.get('expires') and f['expires'] < today]
for f in bad:
    print(f"EXPIRED flag {f['key']} (owner {f['owner']}, due {f['expires']})")
sys.exit(1 if bad else 0)
PY

# 3) run the suite in BOTH configurations, not just the current one
FLAG_OVERRIDES='{"checkout.new-pricing-engine":false}' npm test
FLAG_OVERRIDES='{"checkout.new-pricing-engine":true}'  npm test

# 4) find flags that are code-referenced but no longer in the control plane
#    (and vice versa) - both directions are bugs
grep -rhoE "flags\.[a-zA-Z]+Variation\('([^']+)'" src/ | sed -E "s/.*'(.*)'/\1/" \
  | sort -u > /tmp/in-code.txt
